function longestTwoTopics(topics: number[]): number {
  let best = 0;
  for (let i = 0; i < topics.length; i++) {
    const seen = new Set<number>();
    let j = i;
    while (j < topics.length) {
      seen.add(topics[j]);
      if (seen.size > 2) break;
      j++;
    }
    best = Math.max(best, j - i);
  }
  return best;
}

