function longestTwoTopics(topics: number[]): number {
  const count = new Map<number, number>();
  let left = 0, best = 0;
  for (let right = 0; right < topics.length; right++) {
    count.set(topics[right], (count.get(topics[right]) ?? 0) + 1);
    while (count.size > 2) {
      const t = topics[left++];
      const c = count.get(t)! - 1;
      if (c === 0) count.delete(t); else count.set(t, c);
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

