function longestTwoTopics(topics: number[]): number {
  let a = -1, b = -1;        // b is the most recent topic, a the other one
  let cur = 0, runB = 0, best = 0;
  for (const t of topics) {
    if (t === a || t === b) cur++;
    else cur = runB + 1;     // keep only the trailing run of b, then add t
    if (t === b) runB++;
    else { runB = 1; a = b; b = t; }
    best = Math.max(best, cur);
  }
  return best;
}

